export interface PackageCoordinate {
	name: string;
	version: string;
}

/**
 * A lock coordinate that is not a registry version.
 *
 * pnpm writes `@async/witness@file:vendor/async-witness-0.8.0.tgz` for the one
 * dependency this repository carries itself, and `file:vendor/…` is not a
 * version: there is no registry coordinate to ask OSV about. The audit does not
 * drop the entry and does not invent a version for it. It records it as its own
 * coordinate kind, carrying the sha256 of the committed tarball the entry
 * resolves to — the digest is what makes the entry auditable, so a `file:`
 * coordinate without one is rejected exactly as loudly as a malformed version.
 */
export interface FileLockCoordinate {
	name: string;
	/** The lock coordinate verbatim, e.g. `file:vendor/async-witness-0.8.0.tgz`. */
	version: string;
	kind: 'file';
	/** Repository-relative path to the committed tarball. */
	tarball: string;
	/** sha256 of that tarball's bytes, read from this tree. */
	sha256: string;
}

export type LockCoordinate = PackageCoordinate | FileLockCoordinate;

export function isFileLockCoordinate(value: LockCoordinate): value is FileLockCoordinate {
	return (value as FileLockCoordinate).kind === 'file';
}

/** The `file:<path>` prefix pnpm writes for a tarball dependency. */
export const FILE_COORDINATE_PREFIX = 'file:';

/** Strips the peer-dependency context pnpm appends to a `file:` lock coordinate. */
export function fileCoordinateTarball(version: string): string {
	return packageVersionWithoutPeerContext(version).slice(FILE_COORDINATE_PREFIX.length);
}

