/**
 * Validates one lock coordinate, registry or `file:`.
 *
 * A `file:` coordinate is accepted only in full: the tarball path it names and
 * the sha256 of that tarball's bytes. Accepting the specifier on its own would
 * put an undigested entry in the SBOM, which is the hole this exists to avoid.
 */
export function validateLockCoordinate(value: unknown, label: string): LockCoordinate {
	const coordinate = asRecord(value, label);
	if (coordinate.kind === undefined) return validatePackageCoordinate(value, label);
	if (coordinate.kind !== 'file') throw new Error(`Invalid ${label}.kind`);
	const name = asString(coordinate.name, `${label}.name`);
	const version = asString(coordinate.version, `${label}.version`);
	const tarball = asString(coordinate.tarball, `${label}.tarball`);
	const digest = asString(coordinate.sha256, `${label}.sha256`);
	if (!(unscopedPackageName.test(name) || scopedPackageName.test(name)))
		throw new Error(`Invalid ${label}.name`);
	if (!version.startsWith(FILE_COORDINATE_PREFIX) || fileCoordinateTarball(version) !== tarball)
		throw new Error(`Invalid ${label}.version`);
	if (tarball === '' || tarball.startsWith('/') || tarball.includes('..'))
		throw new Error(`Invalid ${label}.tarball`);
	if (!sha256Hex.test(digest)) throw new Error(`Invalid ${label}.sha256`);
	return { name, version, kind: 'file', tarball, sha256: digest };
}

export function validateLockCoordinates(value: unknown, label: string): LockCoordinate[] {
	if (!Array.isArray(value)) throw new Error(`Invalid ${label}`);
	const seen = new Set<string>();
