		const coordinate = validateLockCoordinate(item, `${label}[${index}]`);
		const key = `${coordinate.name}@${coordinate.version}`;
		if (seen.has(key)) throw new Error(`Duplicate ${label} coordinate: ${key}`);
		seen.add(key);
